"use strict";(function(){const originalLoad=window.loadConfig,originalSave=window.saveConfig;window.loadConfig=function(){const config=originalLoad();config.rentals=(config.rentals||[]).filter(rental=>rental.id!=='uber');config.rentals.push({id:'uber',name:'Uber',type:'VAN',collection:'0001-01-01',return:'9999-12-31',system:true});return config};window.saveConfig=function(config){const clean={...config,rentals:(config.rentals||[]).filter(rental=>rental.id!=='uber')};originalSave(clean)};Editor.rentalEmoji=function(id){const list=(loadConfig().rentals||[]).filter(rental=>rental.id!=='uber'),index=list.findIndex(rental=>rental.id===id);return index>=0&&index<6?['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣'][index]:''};Editor.resetDay=function(day){const key=Editor.dateKey(day);if(!confirm('Reset this day to its default vehicle allocation and run order? Base jobs will return to unassigned.'))return;delete Editor.state().stops[key];delete Editor.state().orders[key];Object.entries(Editor.state().assignments).forEach(([assignmentKey,vehicle])=>{if(Editor.state().jobDates[assignmentKey]===key)delete Editor.state().assignments[assignmentKey]});Editor.refresh()};const apply=Editor.apply;Editor.apply=function(day){const result=apply(day);day.rentals=(day.rentals||[]).filter(rental=>rental.id!=='uber'||rental.rows.some(row=>row.editorStop||row.editorJob));[day.truck,day.van,...day.rentals].filter(Boolean).forEach(run=>run.rows.forEach(row=>{if(row.editorJob)row.transfers=row.transfers.replace(' | Dump ',' | Onsite Time: ')}));return result};window.renderConfig()})();
setTimeout(function(){
 const render=window.renderSchedule;
 function decorate(schedule){document.querySelectorAll('#scheduleOutput .day').forEach((article,index)=>{const day=schedule[index];if(!day)return;const ids=Editor.ids(day);article.querySelectorAll('.warning.base .run-actions').forEach(actions=>{Array.from(actions.querySelectorAll('button')).forEach((button,i)=>{const id=ids[i];if(!id)return;const label='Add to '+Editor.name(id);button.textContent=id==='truck'?'🚚':id==='van'?'🚐':id==='uber'?'🚕':Editor.rentalEmoji(id)||'🚗';button.title=label;button.setAttribute('aria-label',label);button.classList.add('icon-btn');button.style.border='none';button.style.background='transparent';button.style.boxShadow='none';button.style.padding='2px 4px';});});});}
 window.renderSchedule=function(schedule){const result=render(schedule);decorate(schedule);return result;};
 decorate(window.currentSchedule||[]);
},0);
